import { Progress, Button, Card } from "march/ui"

// pizza fırını: "Fırına at" her saniye pişirir; renk pişme durumuna göre maviden turuncuya, sonra kırmızıya döner
export function PizzaOven() {
  let $baked = 0
  let $timer = 0
  const bake = () => {
    clearInterval($timer)
    $baked = 0
    $timer = setInterval(() => { $baked = Math.min(120, $baked + 10); if ($baked >= 120) clearInterval($timer) }, 400) as unknown as number
  }
  const tone = () => ($baked < 60 ? "info" : $baked <= 100 ? "success" : "danger") as "info"
  const say = () => ($baked === 0 ? "Hamur bekliyor" : $baked < 100 ? "Pişiyor…" : $baked === 100 ? "Tam kıvamında! 🍕" : "Yandı! 🔥")
  return <Card title="Pizza fırını">
    <Progress value={() => $baked} max={100} tone={tone} label={say} showValue size="lg" />
    <Button size="sm" on:click={bake}>Fırına at</Button>
  </Card>
}

import { Progress, Button, Card } from "march/ui"

// dosya yükleme kuyruğu: her dosyanın kendi çubuğu MB metniyle; tamamlanan yeşile döner, üstteki ince çizgi toplamı gösterir
const FILES = [{ name: "rapor.pdf", size: 12 }, { name: "tatil.mp4", size: 480 }, { name: "logo.svg", size: 1 }]

export function UploadQueue() {
  let $done: number[] = FILES.map(() => 0)
  let $timer = 0
  const start = () => {
    clearInterval($timer)
    $done = FILES.map(() => 0)
    $timer = setInterval(() => {
      $done = $done.map((d, i) => Math.min(FILES[i]!.size, d + Math.max(1, FILES[i]!.size / 8)))
      if ($done.every((d, i) => d >= FILES[i]!.size)) clearInterval($timer)
    }, 300) as unknown as number
  }
  const total = () => FILES.reduce((a, f) => a + f.size, 0)
  const sent = () => $done.reduce((a, d) => a + d, 0)
  return <Card title="Yüklemeler">
    <Progress variant="line" value={sent} max={total()} ariaLabel="Toplam yükleme" smooth={false} />
    <div sx={{ flex: "col", gap: 2 }}>
      {FILES.map((f, i) => <Progress label={f.name} value={() => $done[i]} max={f.size} size="sm"
        tone={() => ($done[i]! >= f.size ? "success" : "primary")}
        showValue={(_p: number, mb: number) => `${Math.round(mb)} / ${f.size} MB`} />)}
    </div>
    <Button size="sm" variant="primary" on:click={start}>Yüklemeyi başlat</Button>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { ProgressLab } from "./ProgressLab.tsx"

// ProgressLab'in testleri: kaydedince Testler sekmesinde çalışır
test("progressbar adı label'dan gelir; değer düğmeyle artar", async () => {
  const s = renderTest(() => <ProgressLab />)
  const bar = s.get("[aria-label='Ton success']")
  expect(bar?.getAttribute("role")).toBe("progressbar")
  expect(bar?.getAttribute("aria-valuenow")).toBe("40")
  await s.click("+20")
  expect(bar?.getAttribute("aria-valuenow")).toBe("60")
})

test("showValue fonksiyonu kendi metnini, valueText aria-valuetext'i yazar", () => {
  const s = renderTest(() => <ProgressLab />)
  const video = s.get(".lab-video")
  expect(video?.querySelector(".m-progress2-value")?.textContent).toBe("192 / 480 MB (%40)")
  expect(video?.querySelector("[role=progressbar]")?.getAttribute("aria-valuetext")).toBe("192 MB / 480 MB")
})

test("değersiz çubuk belirsiz; decorative yardımcı teknolojiden gizli", () => {
  const s = renderTest(() => <ProgressLab />)
  expect(s.all(".is-indeterminate").length).toBe(1)
  expect(s.get(".lab-line .m-progress2-track")?.getAttribute("aria-hidden")).toBe("true")
  expect(s.get(".lab-vertical")?.classList.contains("m-progress2-vertical")).toBe(true)
})

test("segments parçaları çizer", () => {
  const s = renderTest(() => <ProgressLab />)
  expect(s.get(".lab-story")?.querySelectorAll(".m-progress2-seg").length).toBe(4)
})
